// Validate Verification Request — Panoptes M9

const input = $input.first().json;

const incidentId = input.incident_id ?? null;
const retryExecutionId = input.retry_execution_id ?? null;
const retryCount = Number(input.retry_count);
const maxRetries = Number(input.max_retries);

if (!incidentId || !retryExecutionId) {
  throw new Error(
    'Panoptes verification request missing incident_id or retry_execution_id'
  );
}

if (!Number.isInteger(retryCount) || retryCount < 0) {
  throw new Error('Invalid retry_count');
}

if (!Number.isInteger(maxRetries) || maxRetries < 0) {
  throw new Error('Invalid max_retries');
}

return [{
  json: {
    incident_id: String(incidentId),
    retry_execution_id: String(retryExecutionId),
    retry_count: retryCount,
    max_retries: maxRetries,
  }
}];

// Evaluate Recovery Result — Panoptes M9

const execution = $input.first().json;
const request = $('Validate Verification Request').first().json;

const status = execution.status ?? null;

let recovery_outcome = 'PENDING';
let next_status = 'VERIFYING';
let loop_required = false;
let human_required = false;
let reason = 'Retry execution has not reached a terminal state yet.';

if (status === 'success') {
  recovery_outcome = 'RECOVERED';
  next_status = 'RECOVERED';
  loop_required = false;
  human_required = false;
  reason = 'Retry execution completed successfully.';
}

else if (status === 'error') {
  if (request.retry_count < request.max_retries) {
    recovery_outcome = 'RETRY_FAILED';
    next_status = 'RECOVERY_PENDING';
    loop_required = true;
    human_required = false;
    reason =
      'Retry execution failed, but the incident still has recovery attempts remaining.';
  } else {
    recovery_outcome = 'RETRY_EXHAUSTED';
    next_status = 'ESCALATED';
    loop_required = false;
    human_required = true;
    reason =
      'Retry execution failed and the recovery attempt budget is exhausted.';
  }
}

else if (status === 'canceled' || status === 'crashed') {
  recovery_outcome = 'RETRY_FAILED';
  next_status = 'ESCALATED';
  loop_required = false;
  human_required = true;
  reason =
    `Retry execution ended with terminal status: ${status}.`;
}

return [{
  json: {
    incident_id: request.incident_id,

    retry_execution_id: request.retry_execution_id,
    retry_execution_status: status,

    retry_count: request.retry_count,
    max_retries: request.max_retries,

    recovery_outcome,
    next_status,

    loop_required,
    human_required,

    reason
  }
}];

// Enforce Loop Termination — Panoptes M11.6
// v1.0.1 patch: preserve terminal escalation from verification

const result = $input.first().json;

const retryCount = Number(result.retry_count);
const maxRetries = Number(result.max_retries);

if (!Number.isInteger(retryCount) || retryCount < 0) {
  throw new Error('Invalid retry_count in recovery result');
}

if (!Number.isInteger(maxRetries) || maxRetries < 0) {
  throw new Error('Invalid max_retries in recovery result');
}

const allowedOutcomes = [
  'RECOVERED',
  'RETRY_FAILED',
  'RETRY_EXHAUSTED',
  'PENDING'
];

let recoveryOutcome = String(
  result.recovery_outcome ?? 'PENDING'
).toUpperCase();

let nextStatus = String(
  result.next_status ?? 'VERIFYING'
).toUpperCase();

let loopRequired = Boolean(result.loop_required);
let humanRequired = Boolean(result.human_required);
let terminationReason = null;

// Unknown outcome fails closed.
if (!allowedOutcomes.includes(recoveryOutcome)) {
  recoveryOutcome = 'PENDING';
  nextStatus = 'VERIFYING';
  loopRequired = false;
  humanRequired = true;

  terminationReason =
    'Unknown recovery outcome blocked from automatic continuation.';
}

// Recovery completed.
else if (recoveryOutcome === 'RECOVERED') {
  nextStatus = 'RECOVERED';
  loopRequired = false;
  humanRequired = false;

  terminationReason =
    'Recovery succeeded. No further recovery cycle required.';
}

// Retry failed.
else if (recoveryOutcome === 'RETRY_FAILED') {

  // Preserve a terminal escalation already determined by verification.
  // Example: retry execution was canceled or crashed.
  if (nextStatus === 'ESCALATED') {
    loopRequired = false;
    humanRequired = true;

    terminationReason =
      'Retry execution ended in a terminal state. Incident remains escalated for human attention.';
  }

  // Ordinary retry failure with exhausted budget.
  else if (retryCount >= maxRetries) {
    recoveryOutcome = 'RETRY_EXHAUSTED';
    nextStatus = 'ESCALATED';
    loopRequired = false;
    humanRequired = true;

    terminationReason =
      `Retry budget reached ${retryCount}/${maxRetries}. Recovery loop terminated.`;
  }

  // Ordinary retry failure with attempts remaining.
  else if (nextStatus === 'RECOVERY_PENDING') {
    loopRequired = true;
    humanRequired = false;

    terminationReason =
      `Retry failed, but ${maxRetries - retryCount} recovery attempt(s) remain.`;
  }

  // Unexpected RETRY_FAILED state fails closed.
  else {
    nextStatus = 'ESCALATED';
    loopRequired = false;
    humanRequired = true;

    terminationReason =
      'Unexpected retry-failure state blocked from automatic continuation and escalated for human attention.';
  }
}

// Explicit terminal exhaustion.
else if (recoveryOutcome === 'RETRY_EXHAUSTED') {
  nextStatus = 'ESCALATED';
  loopRequired = false;
  humanRequired = true;

  terminationReason =
    'Retry budget exhausted. Recovery loop terminated.';
}

// Verification hasn't reached a definitive result.
// Never automatically spin another retry.
else if (recoveryOutcome === 'PENDING') {
  nextStatus = 'VERIFYING';
  loopRequired = false;
  humanRequired = true;

  terminationReason =
    'Recovery verification is pending. Automatic retry loop paused.';
}

return [{
  json: {
    ...result,

    recovery_outcome: recoveryOutcome,
    next_status: nextStatus,
    loop_required: loopRequired,
    human_required: humanRequired,

    loop_guard_applied: true,
    loop_termination_reason: terminationReason
  }
}];
